<section class="page-heading reveal"><div><p class="kicker">TRANSACTION ARCHIVE</p><h1>Sales history</h1><p>Every piece, client, quantity, staff member, total, and date in one record.</p></div><a class="button button-red" href="<?= base_url('sales/new') ?>">＋ Record sale</a></section>
<section class="toolbar reveal"><label class="search-box"><span>⌕</span><input type="search" placeholder="Search product, client, or staff" data-search-input="salesTable"></label><span><?= count($sales) ?> transaction(s)</span></section>
<section class="panel table-panel reveal">
