    <?php foreach ($sales as $sale): ?><tr data-search-item="<?= esc(strtolower($sale['product_name'] . ' ' . ($sale['customer_name'] ?? 'walk-in') . ' ' . $sale['staff_name']), 'attr') ?>"><td><a class="transaction-link" href="<?= base_url('sales/' . $sale['id'] . '/receipt') ?>">#<?= str_pad((string) $sale['id'], 5, '0', STR_PAD_LEFT) ?> ↗</a></td><td><div class="identity"><img src="<?= esc(media_url($sale['product_image'], 'products', 'images/product-placeholder.svg'), 'attr') ?>" alt=""><strong><?= esc($sale['product_name']) ?></strong></div></td><td><?= esc($sale['customer_name'] ?? 'Walk-in customer') ?></td><td><?= esc($sale['staff_name']) ?></td><td><?= esc($sale['quantity']) ?></td><td><strong><?= peso($sale['total_price']) ?></strong></td><td><?= esc(date('M j, Y · g:i A', strtotime($sale['created_at']))) ?></td></tr><?php endforeach; ?>
    </tbody></table></div><?php else: ?><div class="empty-state"><span>＋</span><h2>No transactions yet.</h2><p>Record the first CasaForma sale.</p></div><?php endif; ?>
